CREATE TYPE "PickupStatus" AS ENUM ('IN_PROGRESS','COMPLETED','REFUSED','CANCELLED');
CREATE TYPE "PickupItemStatus" AS ENUM ('PENDING','RELEASED','REFUSED');
CREATE TYPE "ResourceCondition" AS ENUM ('OK','DAMAGED','DIVERGENT','OTHER');
CREATE TYPE "PickupRefusalReason" AS ENUM ('DAMAGE','RESOURCE_MISMATCH','DOCUMENT_MISMATCH','RECIPIENT_MISMATCH','RESERVATION_INVALID','OTHER');
CREATE TYPE "EvidenceType" AS ENUM ('DAMAGE','DIVERGENCE','RESOURCE_IDENTIFICATION','OUTPUT_CONDITION');
CREATE TYPE "CustodyEventType" AS ENUM ('RELEASED_TO_RECIPIENT');
CREATE TABLE "ReservationPickup" ("id" UUID PRIMARY KEY,"tenantId" UUID NOT NULL,"reservationId" UUID NOT NULL,"status" "PickupStatus" NOT NULL DEFAULT 'IN_PROGRESS',"startedAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"completedAt" TIMESTAMPTZ(3),"refusedAt" TIMESTAMPTZ(3),"processedByUserId" UUID NOT NULL,"recipientName" TEXT NOT NULL,"recipientDocument" TEXT,"recipientPhone" TEXT,"vehiclePlate" TEXT,"notes" TEXT,"refusalReasonCode" "PickupRefusalReason","refusalNotes" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "ReservationPickupItem" ("id" UUID PRIMARY KEY,"tenantId" UUID NOT NULL,"pickupId" UUID NOT NULL,"reservationItemId" UUID NOT NULL,"resourceId" UUID NOT NULL,"status" "PickupItemStatus" NOT NULL DEFAULT 'PENDING',"condition" "ResourceCondition" NOT NULL DEFAULT 'OK',"notes" TEXT,"checkedAt" TIMESTAMPTZ(3),"checkedByUserId" UUID,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "OperationalEvidence" ("id" UUID PRIMARY KEY,"tenantId" UUID NOT NULL,"pickupId" UUID NOT NULL,"pickupItemId" UUID,"type" "EvidenceType" NOT NULL,"storageKey" TEXT NOT NULL UNIQUE,"mimeType" TEXT NOT NULL,"size" INTEGER NOT NULL,"checksum" TEXT NOT NULL,"uploadedByUserId" UUID NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "ResourceCustodyEvent" ("id" UUID PRIMARY KEY,"tenantId" UUID NOT NULL,"resourceId" UUID NOT NULL,"reservationId" UUID NOT NULL,"pickupId" UUID NOT NULL,"type" "CustodyEventType" NOT NULL,"fromParty" TEXT NOT NULL,"toParty" TEXT NOT NULL,"actorUserId" UUID NOT NULL,"occurredAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"metadata" JSONB);
CREATE UNIQUE INDEX "ReservationPickup_tenantId_id_key" ON "ReservationPickup"("tenantId","id");
CREATE INDEX "ReservationPickup_tenantId_status_createdAt_idx" ON "ReservationPickup"("tenantId","status","createdAt");
CREATE INDEX "ReservationPickup_tenantId_reservationId_createdAt_idx" ON "ReservationPickup"("tenantId","reservationId","createdAt");
CREATE UNIQUE INDEX "ReservationPickup_one_completed_per_reservation" ON "ReservationPickup"("tenantId","reservationId") WHERE "status"='COMPLETED';
CREATE UNIQUE INDEX "ReservationPickupItem_tenantId_id_key" ON "ReservationPickupItem"("tenantId","id");
CREATE UNIQUE INDEX "ReservationPickupItem_pickupId_reservationItemId_key" ON "ReservationPickupItem"("pickupId","reservationItemId");
CREATE INDEX "ReservationPickupItem_tenantId_pickupId_idx" ON "ReservationPickupItem"("tenantId","pickupId");
CREATE INDEX "ReservationPickupItem_tenantId_resourceId_idx" ON "ReservationPickupItem"("tenantId","resourceId");
CREATE INDEX "OperationalEvidence_tenantId_pickupId_createdAt_idx" ON "OperationalEvidence"("tenantId","pickupId","createdAt");
CREATE INDEX "ResourceCustodyEvent_tenantId_resourceId_occurredAt_idx" ON "ResourceCustodyEvent"("tenantId","resourceId","occurredAt");
CREATE INDEX "ResourceCustodyEvent_tenantId_reservationId_idx" ON "ResourceCustodyEvent"("tenantId","reservationId");
ALTER TABLE "ReservationPickup" ADD FOREIGN KEY ("tenantId") REFERENCES "Tenant"("id"), ADD FOREIGN KEY ("tenantId","reservationId") REFERENCES "Reservation"("tenantId","id"), ADD FOREIGN KEY ("processedByUserId") REFERENCES "User"("id");
ALTER TABLE "ReservationPickupItem" ADD FOREIGN KEY ("tenantId") REFERENCES "Tenant"("id"), ADD FOREIGN KEY ("tenantId","pickupId") REFERENCES "ReservationPickup"("tenantId","id") ON DELETE CASCADE, ADD FOREIGN KEY ("reservationItemId") REFERENCES "ReservationItem"("id"), ADD FOREIGN KEY ("tenantId","resourceId") REFERENCES "Resource"("tenantId","id"), ADD FOREIGN KEY ("checkedByUserId") REFERENCES "User"("id");
ALTER TABLE "OperationalEvidence" ADD FOREIGN KEY ("tenantId") REFERENCES "Tenant"("id"), ADD FOREIGN KEY ("tenantId","pickupId") REFERENCES "ReservationPickup"("tenantId","id") ON DELETE CASCADE, ADD FOREIGN KEY ("tenantId","pickupItemId") REFERENCES "ReservationPickupItem"("tenantId","id") ON DELETE CASCADE, ADD FOREIGN KEY ("uploadedByUserId") REFERENCES "User"("id");
ALTER TABLE "ResourceCustodyEvent" ADD FOREIGN KEY ("tenantId") REFERENCES "Tenant"("id"), ADD FOREIGN KEY ("tenantId","resourceId") REFERENCES "Resource"("tenantId","id"), ADD FOREIGN KEY ("tenantId","reservationId") REFERENCES "Reservation"("tenantId","id"), ADD FOREIGN KEY ("tenantId","pickupId") REFERENCES "ReservationPickup"("tenantId","id"), ADD FOREIGN KEY ("actorUserId") REFERENCES "User"("id");
ALTER TABLE "ReservationItem" DROP CONSTRAINT "ReservationItem_no_blocking_overlap";
ALTER TABLE "ReservationItem" ADD CONSTRAINT "ReservationItem_no_blocking_overlap" EXCLUDE USING gist ("tenantId" WITH =,"resourceId" WITH =,tstzrange("startAt","endAt",'[)') WITH &&) WHERE ("status" IN ('PENDING_APPROVAL','APPROVED','CONFIRMED','READY_FOR_PICKUP','RELEASED'));
